  font-family: 'Playfair Display', serif;
}

h1, h2, h3, h4, h5, h6 {
  font-family: 'IM Fell Great Primer', serif;
}

.layout {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  min-height: 100dvh;
  position: relative;
  isolation: isolate;
}

.layout__background {
  position: fixed;
  inset: 0;
  z-index: 0;
  background-image: url('https://static.independent.co.uk/2020/09/17/10/goodfellas-poster.jpg?width=1200&height=1200&fit=crop');
  background-repeat: no-repeat;
  background-size: cover;
  background-position: 72% 28%;
  opacity: 0.28;
  filter: blur(14px) saturate(0.85);
  pointer-events: none;
}

.layout__background::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(
    160deg,
    rgba(11, 7, 16, 0.82) 0%,
    rgba(19, 14, 26, 0.45) 45%,
    rgba(11, 7, 16, 0.88) 100%
  );
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}

.layout__main {
  flex: 1;
  display: flex;
  flex-direction: column;
  width: 100%;
  max-width: var(--content-max-width);
  margin: 0 auto;
  padding: var(--space-lg) var(--space-md);
  position: relative;
  z-index: 1;
}

.header {
  border-bottom: 1px solid var(--color-border);
  background-color: var(--color-bg-elevated);
  padding-top: env(safe-area-inset-top);
  position: relative;
  z-index: 100;
}

.header__bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-md);
  max-width: var(--content-max-width);
  margin: 0 auto;
  padding: var(--space-md);
}

.header__logo {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--color-gold);
  text-decoration: none;
  letter-spacing: 0.02em;
  min-height: var(--touch-target);
  display: flex;
  align-items: center;
}

.header__logo:hover {
  color: var(--color-gold-light);
  text-decoration: none;
}

.header__menu-button {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: var(--touch-target);
  min-height: var(--touch-target);
  padding: 0;
  border: 1px solid var(--color-border);
  border-radius: 0.375rem;
  background-color: var(--color-bg-subtle);
  color: var(--color-gold);
  cursor: pointer;
  transition: border-color 0.2s ease, color 0.2s ease;
}

.header__menu-button:hover {
  border-color: var(--color-gold-muted);
  color: var(--color-gold-light);
}

.header__menu-icon {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 0.3rem;
  width: 1.25rem;
}

.header__menu-icon span {
  display: block;
  height: 2px;
  width: 100%;
  background-color: currentColor;
  border-radius: 1px;
  transition: transform 0.2s ease, opacity 0.2s ease;
}

.header__menu-button--open .header__menu-icon span:nth-child(1) {
  transform: translateY(0.45rem) rotate(45deg);
}

.header__menu-button--open .header__menu-icon span:nth-child(2) {
  opacity: 0;
}

.header__menu-button--open .header__menu-icon span:nth-child(3) {
  transform: translateY(-0.45rem) rotate(-45deg);
}

.header__backdrop {
  position: fixed;
  inset: 0;
  z-index: 110;
  border: none;
  padding: 0;
  background-color: rgba(11, 7, 16, 0.72);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.2s ease, visibility 0.2s ease;
  cursor: pointer;
}

.header__backdrop--visible {
  opacity: 1;
  visibility: visible;
}

.header__nav {
  position: fixed;
  top: 0;
  right: 0;
  z-index: 120;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: var(--space-xl);
  width: min(18rem, 88vw);
  height: 100%;
  height: 100dvh;
  padding: calc(var(--space-xl) + env(safe-area-inset-top)) var(--space-lg)
    calc(var(--space-xl) + env(safe-area-inset-bottom));
  background-color: var(--color-bg-elevated);
  border-left: 1px solid var(--color-border);
  transform: translateX(100%);
  transition: transform 0.25s ease;
  overflow-y: auto;
}

.header__nav--open {
  transform: translateX(0);
}

.header__nav-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: var(--space-xs);
}

.header__nav-list--auth {
  padding-top: var(--space-lg);
  border-top: 1px solid var(--color-border);
}

.header__nav-link {
  display: flex;
  align-items: center;
  min-height: var(--touch-target);
  padding: var(--space-sm) var(--space-md);
  font-size: var(--font-size-base);
  color: var(--color-crimson);
  border-radius: 0.375rem;
  transition: background-color 0.2s ease, color 0.2s ease;
}

.header__nav-link:hover {
  color: var(--color-crimson-light);
  background-color: var(--color-bg-subtle);
  text-decoration: none;
}

.header__nav-link--active {
  color: var(--color-gold);
  background-color: var(--color-bg-subtle);
}

.header__nav-list--auth .header__nav-link {
  color: var(--color-gold-muted);
}

.header__nav-list--auth .header__nav-link:hover,
.header__nav-list--auth .header__nav-link--active {
  color: var(--color-gold);
}

.page {
  flex: 1;
  padding: var(--space-xl) 0;
}

.page__title {
  font-size: clamp(1.75rem, 6vw, 2.5rem);
  font-weight: 800;
  color: var(--color-gold);
  margin-bottom: var(--space-lg);
  letter-spacing: 0.02em;
}

.page__content {
  font-size: var(--font-size-lg);
  color: var(--color-gold-muted);
  max-width: 40rem;
  line-height: 1.6;
}

.hero {
  position: relative;
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-xl) 0;
  min-height: calc(100dvh - 12rem);
  text-align: center;
}

.hero__content {
  position: relative;
  z-index: 1;
  width: 100%;
}

.hero__eyebrow {
  font-size: var(--font-size-sm);
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-crimson);
  margin-bottom: var(--space-sm);
}

.hero h1 {
  font-size: clamp(2rem, 10vw, 3.5rem);
  font-weight: 800;
  margin-bottom: var(--space-md);
  color: var(--color-gold);
  letter-spacing: 0.03em;
  text-shadow: 0 0 40px rgba(212, 175, 55, 0.15);
  height: 100vh
}

.hero__tagline {
  font-size: var(--font-size-lg);
  color: var(--color-gold-muted);
  max-width: 32rem;
  margin: 0 auto;
  padding: 0 var(--space-sm);
}

.footer {
  border-top: 1px solid var(--color-border);
  background-color: var(--color-bg-elevated);
  padding: var(--space-lg) var(--space-md);
  padding-bottom: calc(var(--space-lg) + env(safe-area-inset-bottom));
  text-align: center;
  font-size: var(--font-size-sm);
  color: var(--color-crimson);
  position: relative;
  z-index: 1;
}

@media (min-width: 640px) {
  .layout__main {
    padding: var(--space-xl) var(--space-lg);
  }

  .header__bar {
    padding: var(--space-md) var(--space-lg);
  }

  .header__logo {
    font-size: 1.25rem;
  }

  .hero {
    padding: var(--space-2xl) 0;
    min-height: calc(100dvh - 10rem);
  }

  .layout__background {
    opacity: 0.32;
    filter: blur(12px) saturate(0.9);
  }
}

@media (min-width: 960px) {
  .layout__background {
    background-position: 68% 30%;
    opacity: 0.34;
    filter: blur(10px) saturate(0.9);
  }
}
