   GOODFELLAS DETAILING CALENDAR
   ========================================= */

.detailing-calendar {
  width: 100%;
  max-width: 1000px;
  margin: 40px auto;
  padding: 30px;

  background:
    linear-gradient(
      145deg,
      #17101b,
      #0d090f
    );

  color: #d4af37;

  border: 1px solid #4a1b2a;
  border-radius: 10px;

  box-shadow:
    0 20px 50px rgba(0, 0, 0, 0.6),
    inset 0 0 40px rgba(90, 0, 30, 0.08);

  font-family:
    Georgia,
    "Times New Roman",
    serif;
}


/* =========================================
   HEADER
   ========================================= */

.calendar-header {
  display: flex;
  justify-content: space-between;
  align-items: center;

  margin-bottom: 25px;

  border-bottom: 1px solid #3a1725;
  padding-bottom: 20px;
}

.calendar-header h2 {
  margin: 0;

  color: #d4af37;

  font-size: 28px;
  letter-spacing: 1px;

  text-shadow:
    0 2px 4px #000;
}

.calendar-header p {
  margin: 6px 0 0;

  color: #a8949e;

  font-family:
    Arial,
    sans-serif;

  font-size: 14px;
}

.today-button {
  padding: 9px 18px;

  background: transparent;

  color: #d4af37;

  border: 1px solid #8b6f24;
  border-radius: 5px;

  cursor: pointer;

  font-family: Georgia, serif;
  font-weight: bold;

  transition: all 0.2s ease;
}

.today-button:hover {
  background: #64152b;
  border-color: #d4af37;
}


/* =========================================
   MONTH NAVIGATION
   ========================================= */

.calendar-navigation {
  display: flex;
  align-items: center;
  justify-content: center;

  gap: 30px;

  margin-bottom: 20px;
}

.calendar-navigation h3 {
  min-width: 220px;

  margin: 0;

  text-align: center;

  color: #d4af37;

  font-size: 22px;
}

.nav-button {
  width: 40px;
  height: 40px;

  background: #24131f;

  color: #d4af37;

  border: 1px solid #5b2133;
  border-radius: 50%;

  font-size: 28px;
  line-height: 30px;

  cursor: pointer;

  transition: all 0.2s ease;
}

.nav-button:hover {
  background: #64152b;
  border-color: #d4af37;
}


/* =========================================
   CALENDAR GRID
   ========================================= */

.calendar-grid {
  display: grid;

  grid-template-columns:
    repeat(7, 1fr);

  border-top: 1px solid #42202d;
  border-left: 1px solid #42202d;
}

.calendar-day-name {
  padding: 12px 5px;

  text-align: center;

  color: #a8949e;

  background: #130c14;

  border-right: 1px solid #42202d;
  border-bottom: 1px solid #42202d;

  font-family: Arial, sans-serif;
  font-size: 12px;
  font-weight: bold;

  text-transform: uppercase;
  letter-spacing: 1px;
}


/* =========================================
   CALENDAR CELLS
   ========================================= */

.calendar-cell {
  position: relative;

  min-height: 100px;

  padding: 10px;

  background: #171019;

  color: #c8bbc1;

  border: none;
  border-right: 1px solid #42202d;
  border-bottom: 1px solid #42202d;

  text-align: left;

  cursor: pointer;

  font-family: Georgia, serif;

  transition:
    background 0.15s ease,
    box-shadow 0.15s ease;
}

.calendar-cell:hover {
  background: #251321;

  box-shadow:
    inset 0 0 0 1px #6b2035;
}

.calendar-cell.empty {
  background: #100b11;

  cursor: default;
}

.calendar-cell.empty:hover {
  box-shadow: none;
}


/* =========================================
   DATE NUMBER
   ========================================= */

.calendar-date {
  display: block;

  margin-bottom: 8px;

  color: #bca7af;

  font-size: 16px;
}


/* =========================================
   TODAY
   ========================================= */

.calendar-cell.today {
  box-shadow:
    inset 0 0 0 2px #8b6f24;
}

.calendar-cell.today .calendar-date {
  color: #d4af37;

  font-weight: bold;
}


/* =========================================
   SELECTED DAY
   ========================================= */

.calendar-cell.selected {
  background: #3a1323;

  box-shadow:
    inset 0 0 0 2px #a51c3d;
}

.calendar-cell.selected .calendar-date {
  color: #f0c94b;
}


/* =========================================
   APPOINTMENT INDICATOR
   ========================================= */

.appointment-indicator {
  display: flex;
  align-items: center;

  gap: 6px;

  width: fit-content;

  padding: 4px 7px;

  background: #4b1327;

  border-left: 3px solid #a51c3d;

  color: #e2c55c;

  font-family: Arial, sans-serif;

  font-size: 11px;
  font-weight: bold;

  border-radius: 2px;
}

.appointment-dot {
  width: 6px;
  height: 6px;

  background: #a51c3d;

  border-radius: 50%;

  box-shadow:
    0 0 5px rgba(165, 28, 61, 0.8);
}


/* =========================================
   CALENDAR LEGEND
   ========================================= */

.calendar-legend {
  display: flex;

  gap: 25px;

  margin-top: 15px;

  color: #8e7c85;

  font-family: Arial, sans-serif;
  font-size: 12px;
}

.calendar-legend span {
  display: flex;
  align-items: center;

  gap: 7px;
}

.legend-dot {
  width: 8px;
  height: 8px;

  background: #a51c3d;

  border-radius: 50%;
}

.legend-ring {
  width: 8px;
  height: 8px;

  border: 2px solid #d4af37;

  border-radius: 50%;
}


/* =========================================
   APPOINTMENT FORM
   ========================================= */

.appointment-form {
  margin-top: 30px;
  padding: 25px;

  background:
    linear-gradient(
      145deg,
      #21121d,
      #120b13
    );

  border: 1px solid #642039;
  border-left: 4px solid #a51c3d;

  border-radius: 6px;

  box-shadow:
    0 12px 30px rgba(0, 0, 0, 0.4);
}

.form-header {
  display: flex;
  justify-content: space-between;
  align-items: center;

  margin-bottom: 20px;

  padding-bottom: 15px;

  border-bottom: 1px solid #3d1b29;
}

.form-header h3 {
  margin: 0;

  color: #d4af37;

  font-size: 20px;
}

.form-header span {
  color: #a51c3d;

  font-family: Arial, sans-serif;
  font-weight: bold;
}


/* =========================================
   FORM ELEMENTS
   ========================================= */

.form-group {
  margin-bottom: 20px;
}

.form-group label,
.service-options legend {
  display: block;

  margin-bottom: 8px;

  color: #c6a94a;

  font-family: Arial, sans-serif;
  font-size: 13px;
  font-weight: bold;
}

.form-group input,
.form-group textarea {
  box-sizing: border-box;

  width: 100%;

  padding: 11px;

  background: #0e0a10;

  color: #d7c8ce;

  border: 1px solid #4c2635;
  border-radius: 4px;

  font-family: Arial, sans-serif;

  outline: none;
}

.form-group input:focus,
.form-group textarea:focus {
  border-color: #a51c3d;

  box-shadow:
    0 0 0 2px rgba(165, 28, 61, 0.15);
}

.form-group textarea {
  resize: vertical;
}


/* =========================================
   SERVICE OPTIONS
   ========================================= */

.service-options {
  display: flex;

  gap: 10px;

  margin: 0 0 20px;

  padding: 0;

  border: none;
}

.service-options legend {
  width: 100%;

  margin-bottom: 10px;
}

.service-option {
  flex: 1;

  padding: 12px;

  background: #160d15;

  color: #a8959e;

  border: 1px solid #44202f;
  border-radius: 4px;

  cursor: pointer;

  text-align: center;

  font-family: Arial, sans-serif;
  font-size: 13px;

  transition: all 0.2s ease;
}

.service-option input {
  display: none;
}

.service-option:hover {
  border-color: #7c2943;

  color: #d4af37;
}

.service-option.active {
  background: #461326;

  border-color: #a51c3d;

  color: #e2bd45;

  box-shadow:
    inset 0 0 12px rgba(165, 28, 61, 0.2);
}


/* =========================================
   FORM BUTTONS
   ========================================= */

.appointment-actions {
  display: flex;

  justify-content: flex-end;

  gap: 10px;

  margin-top: 25px;
}

.cancel-button,
.book-button {
  padding: 11px 20px;

  border-radius: 4px;

  font-family: Georgia, serif;
  font-weight: bold;

  cursor: pointer;

  transition: all 0.2s ease;
}

.cancel-button {
  background: transparent;

  color: #95858c;

  border: 1px solid #49303b;
}

.cancel-button:hover {
  color: #d4af37;

  border-color: #8b6f24;
}

.book-button {
  background: #74152e;

  color: #f0ce58;

  border: 1px solid #a51c3d;

  box-shadow:
    0 3px 8px rgba(0, 0, 0, 0.4);
}

.book-button:hover {
  background: #961b3c;

  color: #ffe58a;

  box-shadow:
    0 4px 12px rgba(165, 28, 61, 0.3);
}


/* =========================================
   APPOINTMENT SUMMARY
   ========================================= */

.appointment-summary {
  margin-top: 35px;

  padding-top: 25px;

  border-top: 1px solid #3a1725;
}

.appointment-summary h3 {
  margin-top: 0;

  color: #d4af37;

  font-size: 19px;
}

.appointment-card {
  display: flex;

  gap: 20px;

  margin-bottom: 10px;
  padding: 15px;

  background: #160d15;

  border-left: 3px solid #a51c3d;
  border-radius: 3px;
}

.appointment-date {
  min-width: 100px;

  color: #d4af37;

  font-weight: bold;
}

.appointment-details {
  display: flex;

  flex-direction: column;

  gap: 4px;

  font-family: Arial, sans-serif;
  font-size: 13px;
}

.appointment-details strong {
  color: #c5b6bd;
}

.appointment-details span {
  color: #a51c3d;

  font-weight: bold;

  text-transform: capitalize;
}

.appointment-details p {
  margin: 5px 0 0;

  color: #8e7c85;
}


/* =========================================
   MOBILE
   ========================================= */

@media (max-width: 700px) {

  .detailing-calendar {
    margin: 20px auto;
    padding: 15px;
  }

  .calendar-header {
    align-items: flex-start;
  }

  .calendar-header h2 {
    font-size: 22px;
  }

  .calendar-header p {
    display: none;
  }

  .calendar-cell {
    min-height: 70px;

    padding: 6px;
  }

  .appointment-indicator {
    padding: 3px;

    border-left: 2px solid #a51c3d;

    font-size: 0;
  }

  .appointment-indicator span:last-child {
    display: none;
  }

  .appointment-dot {
    width: 7px;
    height: 7px;
  }

  .service-options {
    flex-direction: column;
  }

  .form-header {
    flex-direction: column;
    align-items: flex-start;

    gap: 5px;
  }

  .appointment-card {
    flex-direction: column;

    gap: 5px;
  }
