========================== */\n\n.calendar-navigation {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n\n  gap: 30px;\n\n  margin-bottom: 20px;\n}\n\n.calendar-navigation h3 {\n  min-width: 220px;\n\n  margin: 0;\n\n  text-align: center;\n\n  color: #d4af37;\n\n  font-size: 22px;\n}\n\n.nav-button {\n  width: 40px;\n  height: 40px;\n\n  background: #24131f;\n\n  color: #d4af37;\n\n  border: 1px solid #5b2133;\n  border-radius: 50%;\n\n  font-size: 28px;\n  line-height: 30px;\n\n  cursor: pointer;\n\n  transition: all 0.2s ease;\n}\n\n.nav-button:hover {\n  background: #64152b;\n  border-color: #d4af37;\n}\n\n\n/* =========================================\n   CALENDAR GRID\n   ========================================= */\n\n.calendar-grid {\n  display: grid;\n\n  grid-template-columns:\n    repeat(7, 1fr);\n\n  border-top: 1px solid #42202d;\n  border-left: 1px solid #42202d;\n}\n\n.calendar-day-name {\n  padding: 12px 5px;\n\n  text-align: center;\n\n  color: #a8949e;\n\n  background: #130c14;\n\n  border-right: 1px solid #42202d;\n  border-bottom: 1px solid #42202d;\n\n  font-family: Arial, sans-serif;\n  font-size: 12px;\n  font-weight: bold;\n\n  text-transform: uppercase;\n  letter-spacing: 1px;\n}\n\n\n/* =========================================\n   CALENDAR CELLS\n   ========================================= */\n\n.calendar-cell {\n  position: relative;\n\n  min-height: 100px;\n\n  padding: 10px;\n\n  background: #171019;\n\n  color: #c8bbc1;\n\n  border: none;\n  border-right: 1px solid #42202d;\n  border-bottom: 1px solid #42202d;\n\n  text-align: left;\n\n  cursor: pointer;\n\n  font-family: Georgia, serif;\n\n  transition:\n    background 0.15s ease,\n    box-shadow 0.15s ease;\n}\n\n.calendar-cell:hover {\n  background: #251321;\n\n  box-shadow:\n    inset 0 0 0 1px #6b2035;\n}\n\n.calendar-cell.empty {\n  background: #100b11;\n\n  cursor: default;\n}\n\n.calendar-cell.empty:hover {\n  box-shadow: none;\n}\n\n\n/* =========================================\n   DATE NUMBER\n   ========================================= */\n\n.calendar-date {\n  display: block;\n\n  margin-bottom: 8px;\n\n  color: #bca7af;\n\n  font-size: 16px;\n}\n\n\n/* =========================================\n   TODAY\n   ========================================= */\n\n.calendar-cell.today {\n  box-shadow:\n    inset 0 0 0 2px #8b6f24;\n}\n\n.calendar-cell.today .calendar-date {\n  color: #d4af37;\n\n  font-weight: bold;\n}\n\n\n/* =========================================\n   SELECTED DAY\n   ========================================= */\n\n.calendar-cell.selected {\n  background: #3a1323;\n\n  box-shadow:\n    inset 0 0 0 2px #a51c3d;\n}\n\n.calendar-cell.selected .calendar-date {\n  color: #f0c94b;\n}\n\n\n/* =========================================\n   APPOINTMENT INDICATOR\n   ========================================= */\n\n.appointment-indicator {\n  display: flex;\n  align-items: center;\n\n  gap: 6px;\n\n  width: fit-content;\n\n  padding: 4px 7px;\n\n  background: #4b1327;\n\n  border-left: 3px solid #a51c3d;\n\n  color: #e2c55c;\n\n  font-family: Arial, sans-serif;\n\n  font-size: 11px;\n  font-weight: bold;\n\n  border-radius: 2px;\n}\n\n.appointment-dot {\n  width: 6px;\n  height: 6px;\n\n  background: #a51c3d;\n\n  border-radius: 50%;\n\n  box-shadow:\n    0 0 5px rgba(165, 28, 61, 0.8);\n}\n\n\n/* =========================================\n   CALENDAR LEGEND\n   ========================================= */\n\n.calendar-legend {\n  display: flex;\n\n  gap: 25px;\n\n  margin-top: 15px;\n\n  color: #8e7c85;\n\n  font-family: Arial, sans-serif;\n  font-size: 12px;\n}\n\n.calendar-legend span {\n  display: flex;\n  align-items: center;\n\n  gap: 7px;\n}\n\n.legend-dot {\n  width: 8px;\n  height: 8px;\n\n  background: #a51c3d;\n\n  border-radius: 50%;\n}\n\n.legend-ring {\n  width: 8px;\n  height: 8px;\n\n  border: 2px solid #d4af37;\n\n  border-radius: 50%;\n}\n\n\n/* =========================================\n   APPOINTMENT FORM\n   ========================================= */\n\n.appointment-form {\n  margin-top: 30px;\n  padding: 25px;\n\n  background:\n    linear-gradient(\n      145deg,\n      #21121d,\n      #120b13\n    );\n\n  border: 1px solid #642039;\n  border-left: 4px solid #a51c3d;\n\n  border-radius: 6px;\n\n  box-shadow:\n    0 12px 30px rgba(0, 0, 0, 0.4);\n}\n\n.form-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n\n  margin-bottom: 20px;\n\n  padding-bottom: 15px;\n\n  border-bottom: 1px solid #3d1b29;\n}\n\n.form-header h3 {\n  margin: 0;\n\n  color: #d4af37;\n\n  font-size: 20px;\n}\n\n.form-header span {\n  color: #a51c3d;\n\n  font-family: Arial, sans-serif;\n  font-weight: bold;\n}\n\n\n/* =========================================\n   FORM ELEMENTS\n   ========================================= */\n\n.form-group {\n  margin-bottom: 20px;\n}\n\n.form-group label,\n.service-options legend {\n  display: block;\n\n  margin-bottom: 8px;\n\n  color: #c6a94a;\n\n  font-family: Arial, sans-serif;\n  font-size: 13px;\n  font-weight: bold;\n}\n\n.form-group input,\n.form-group textarea {\n  box-sizing: border-box;\n\n  width: 100%;\n\n  padding: 11px;\n\n  background: #0e0a10;\n\n  color: #d7c8ce;\n\n  border: 1px solid #4c2635;\n  border-radius: 4px;\n\n  font-family: Arial, sans-serif;\n\n  outline: none;\n}\n\n.form-group input:focus,\n.form-group textarea:focus {\n  border-color: #a51c3d;\n\n  box-shadow:\n    0 0 0 2px rgba(165, 28, 61, 0.15);\n}\n\n.form-group textarea {\n  resize: vertical;\n}\n\n\n/* =========================================\n   SERVICE OPTIONS\n   ========================================= */\n\n.service-options {\n  display: flex;\n\n  gap: 10px;\n\n  margin: 0 0 20px;\n\n  padding: 0;\n\n  border: none;\n}\n\n.service-options legend {\n  width: 100%;\n\n  margin-bottom: 10px;\n}\n\n.service-option {\n  flex: 1;\n\n  padding: 12px;\n\n  background: #160d15;\n\n  color: #a8959e;\n\n  border: 1px solid #44202f;\n  border-radius: 4px;\n\n  cursor: pointer;\n\n  text-align: center;\n\n  font-family: Arial, sans-serif;\n  font-size: 13px;\n\n  transition: all 0.2s ease;\n}\n\n.service-option input {\n  display: none;\n}\n\n.service-option:hover {\n  border-color: #7c2943;\n\n  color: #d4af37;\n}\n\n.service-option.active {\n  background: #461326;\n\n  border-color: #a51c3d;\n\n  color: #e2bd45;\n\n  box-shadow:\n    inset 0 0 12px rgba(165, 28, 61, 0.2);\n}\n\n\n/* =========================================\n   FORM BUTTONS\n   ========================================= */\n\n.appointment-actions {\n  display: flex;\n\n  justify-content: flex-end;\n\n  gap: 10px;\n\n  margin-top: 25px;\n}\n\n.cancel-button,\n.book-button {\n  padding: 11px 20px;\n\n  border-radius: 4px;\n\n  font-family: Georgia, serif;\n  font-weight: bold;\n\n  cursor: pointer;\n\n  transition: all 0.2s ease;\n}\n\n.cancel-button {\n  background: transparent;\n\n  color: #95858c;\n\n  border: 1px solid #49303b;\n}\n\n.cancel-button:hover {\n  color: #d4af37;\n\n  border-color: #8b6f24;\n}\n\n.book-button {\n  background: #74152e;\n\n  color: #f0ce58;\n\n  border: 1px solid #a51c3d;\n\n  box-shadow:\n    0 3px 8px rgba(0, 0, 0, 0.4);\n}\n\n.book-button:hover {\n  background: #961b3c;\n\n  color: #ffe58a;\n\n  box-shadow:\n    0 4px 12px rgba(165, 28, 61, 0.3);\n}\n\n\n/* =========================================\n   APPOINTMENT SUMMARY\n   ========================================= */\n\n.appointment-summary {\n  margin-top: 35px;\n\n  padding-top: 25px;\n\n  border-top: 1px solid #3a1725;\n}\n\n.appointment-summary h3 {\n  margin-top: 0;\n\n  color: #d4af37;\n\n  font-size: 19px;\n}\n\n.appointment-card {\n  display: flex;\n\n  gap: 20px;\n\n  margin-bottom: 10px;\n  padding: 15px;\n\n  background: #160d15;\n\n  border-left: 3px solid #a51c3d;\n  border-radius: 3px;\n}\n\n.appointment-date {\n  min-width: 100px;\n\n  color: #d4af37;\n\n  font-weight: bold;\n}\n\n.appointment-details {\n  display: flex;\n\n  flex-direction: column;\n\n  gap: 4px;\n\n  font-family: Arial, sans-serif;\n  font-size: 13px;\n}\n\n.appointment-details strong {\n  color: #c5b6bd;\n}\n\n.appointment-details span {\n  color: #a51c3d;\n\n  font-weight: bold;\n\n  text-transform: capitalize;\n}\n\n.appointment-details p {\n  margin: 5px 0 0;\n\n  color: #8e7c85;\n}\n\n\n/* =========================================\n   MOBILE\n   ========================================= */\n\n@media (max-width: 700px) {\n\n  .detailing-calendar {\n    margin: 20px auto;\n    padding: 15px;\n  }\n\n  .calendar-header {\n    align-items: flex-start;\n  }\n\n  .calendar-header h2 {\n    font-size: 22px;\n  }\n\n  .calendar-header p {\n    display: none;\n  }\n\n  .calendar-cell {\n    min-height: 70px;\n\n    padding: 6px;\n  }\n\n  .appointment-indicator {\n    padding: 3px;\n\n    border-left: 2px solid #a51c3d;\n\n    font-size: 0;\n  }\n\n  .appointment-indicator span:last-child {\n    display: none;\n  }\n\n  .appointment-dot {\n    width: 7px;\n    height: 7px;\n  }\n\n  .service-options {\n    flex-direction: column;\n  }\n\n  .form-header {\n    flex-direction: column;\n    align-items: flex-start;\n\n    gap: 5px;\n  }\n\n  .appointment-card {\n    flex-direction: column;\n\n    gap: 5px;\n  }\n}"],"sourceRoot":""}]);
