   BANNER
   ========================================= */

.banner {
  --scroll-progress: 0;

  position: relative;

  width: 100%;
  height: 100vh;

  min-height: 500px;

  overflow: hidden;

  display: flex;
  align-items: center;

  box-sizing: border-box;

  background: #100a12;

  isolation: isolate;
}


/* =========================================
   BACKGROUND IMAGE
   ========================================= */

.banner-background {
  position: absolute;

  /*
    Oversized so the image can move around
    without exposing the edges.
  */
  inset: -10%;

  z-index: -3;

  background-image: var(--banner-image);

  background-size: cover;
  background-position: center center;
  background-repeat: no-repeat;

  /*
    Ken Burns effect.

    Starts slightly zoomed and moves through
    a subtle vertical range as the user scrolls.
  */
  transform:
    scale(
      calc(
        1.08 +
        (var(--scroll-progress) * 0.06)
      )
    )
    translateY(
      calc(
        (var(--scroll-progress) - 0.5)
        * -80px
      )
    );

  /*
    Browser can optimize this element because
    it is going to be transformed.
  */
  will-change: transform;

  /*
    Smoothness.
  */
  backface-visibility: hidden;
}


/* =========================================
   DARK PURPLE IMAGE OVERLAY
   ========================================= */

.banner-overlay {
  position: absolute;

  inset: 0;

  z-index: -2;

  /*
    Deep purple-black overlay.
  */
  background:
    linear-gradient(
      90deg,
      rgba(12, 6, 14, 0.72),
      rgba(18, 7, 16, 0.48),
      rgba(10, 5, 12, 0.62)
    );

  /*
    Additional cinematic vignette.
  */
  box-shadow:
    inset 0 0 180px
    rgba(0, 0, 0, 0.75);

  pointer-events: none;
}


/* =========================================
   CONTENT
   ========================================= */

.banner-content {
  position: relative;

  z-index: 2;

  width: 100%;

  padding: 60px;

  box-sizing: border-box;

  /*
    The text moves slightly slower than the
    background, creating depth.
  */
  transform:
    translateY(
      calc(
        (var(--scroll-progress) - 0.5)
        * -45px
      )
    );

  opacity:
    calc(
      1 -
      (
        abs(
          var(--scroll-progress) - 0.5
        ) * 0.55
      )
    );

  will-change: transform, opacity;
}


/* =========================================
   HEADLINE
   ========================================= */

.banner h1 {
  max-width: 900px;

  margin: 0;

  color: #d4af37;

  font-family:
    Georgia,
    "Times New Roman",
    serif;

  font-size: clamp(
    3rem,
    7vw,
    6.5rem
  );

  line-height: 1.05;

  font-weight: 700;

  letter-spacing: 2px;

  text-shadow:
    0 3px 6px rgba(0, 0, 0, 0.95),
    0 0 35px rgba(0, 0, 0, 0.65);

  /*
    Initial entrance.
  */
  animation:
    banner-title-in 1.1s
    cubic-bezier(0.22, 1, 0.36, 1)
    both;
}


/* =========================================
   LEFT
   ========================================= */

.banner-left {
  justify-content: flex-start;

  text-align: left;
}

.banner-left .banner-content {
  display: flex;

  justify-content: flex-start;
}


/* =========================================
   CENTER
   ========================================= */

.banner-center {
  justify-content: center;

  text-align: center;
}

.banner-center .banner-content {
  display: flex;

  justify-content: center;
}

.banner-center h1 {
  margin-left: auto;
  margin-right: auto;
}


/* =========================================
   RIGHT
   ========================================= */

.banner-right {
  justify-content: flex-end;

  text-align: right;
}

.banner-right .banner-content {
  display: flex;

  justify-content: flex-end;
}

.banner-right h1 {
  margin-left: auto;
}


/* =========================================
   INITIAL TITLE ANIMATION
   ========================================= */

@keyframes banner-title-in {

  from {
    opacity: 0;

    transform:
      translateY(40px);
  }

  to {
    opacity: 1;

    transform:
      translateY(0);
  }

}


/* =========================================
   SCROLL INDICATOR
   ========================================= */

.banner-scroll-indicator {
  position: absolute;

  bottom: 30px;
  left: 50%;

  width: 24px;
  height: 40px;

  transform: translateX(-50%);

  border: 1px solid
    rgba(212, 175, 55, 0.6);

  border-radius: 20px;

  z-index: 4;

  opacity:
    calc(
      1 -
      var(--scroll-progress) * 3
    );

  transition: opacity 0.2s ease;
}

.banner-scroll-indicator span {
  position: absolute;

  top: 7px;
  left: 50%;

  width: 4px;
  height: 7px;

  transform: translateX(-50%);

  background: #d4af37;

  border-radius: 4px;

  animation:
    scroll-dot 1.8s
    ease-in-out
    infinite;
}

@keyframes scroll-dot {

  0% {
    opacity: 0;
    transform:
      translate(-50%, 0);
  }

  30% {
    opacity: 1;
  }

  70% {
    opacity: 1;
  }

  100% {
    opacity: 0;
    transform:
      translate(-50%, 17px);
  }

}


/* =========================================
   CRIMSON ACCENT
   ========================================= */

.banner h1::after {
  content: "";

  display: block;

  width: 80px;
  height: 3px;

  margin-top: 25px;

  background: #a51c3d;

  box-shadow:
    0 0 10px
    rgba(165, 28, 61, 0.5);
}


/* Center the accent
   when text is centered */

.banner-center h1::after {
  margin-left: auto;
  margin-right: auto;
}


/* Right align accent */

.banner-right h1::after {
  margin-left: auto;
}


/* =========================================
   TABLET
   ========================================= */

@media (max-width: 900px) {

  .banner-content {
    padding: 40px;
  }

  .banner h1 {
    max-width: 700px;

    font-size: clamp(
      2.75rem,
      8vw,
      5rem
    );
  }

}


/* =========================================
   MOBILE
   ========================================= */

@media (max-width: 600px) {

  .banner {
    /*
      svh handles mobile browser chrome
      considerably better than 100vh.
    */
    height: 100svh;

    min-height: 500px;
  }

  .banner-background {
    /*
      Mobile devices don't always handle
      large fixed backgrounds efficiently.

      We still get our parallax effect from
      transform.
    */
    inset: -15%;

    transform:
      scale(
        calc(
          1.12 +
          (var(--scroll-progress) * 0.05)
        )
      )
      translateY(
        calc(
          (var(--scroll-progress) - 0.5)
          * -50px
        )
      );
  }

  .banner-content {
    padding: 30px 24px;

    transform:
      translateY(
        calc(
          (var(--scroll-progress) - 0.5)
          * -25px
        )
      );
  }

  .banner h1 {
    max-width: 100%;

    font-size: clamp(
      2.4rem,
      12vw,
      4rem
    );

    line-height: 1.08;

    letter-spacing: 1px;
  }

  .banner h1::after {
    width: 55px;

    margin-top: 20px;
  }

  .banner-scroll-indicator {
    bottom: 20px;
  }

}


/* =========================================
   VERY SMALL PHONES
   ========================================= */

@media (max-width: 380px) {

  .banner-content {
    padding: 24px 18px;
  }

  .banner h1 {
    font-size: 2.2rem;
  }

}


/* =========================================
   REDUCED MOTION
   ========================================= */

@media (prefers-reduced-motion: reduce) {

  .banner-background {
    transform: scale(1.05);
    will-change: auto;
  }

  .banner-content {
    transform: none;
    opacity: 1;
    will-change: auto;
  }

  .banner h1 {
    animation: none;
  }

  .banner-scroll-indicator {
    display: none;
  }

}
